create table public.notifications (id uuid primary key default gen_random_uuid(), store_id uuid references public.stores(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, channel text not null check(channel in ('in_app','email','sms','push')), template_key text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'queued' check(status in ('queued','sent','failed','read')), idempotency_key text, created_at timestamptz not null default now(), sent_at timestamptz, read_at timestamptz, unique(user_id,idempotency_key));
